//! Paper texture sets (pre-rendered tileable PNGs under `assets/textures/`,
//! generated by `scripts/gen-textures.py`).
//!
//! Textures are tiled behind surfaces with CSS `background-image` (no blur,
//! no per-frame cost beyond a repeated texture blit, so they stay cheap on
//! software rendering). The texel alpha is capped at [`MAX_TEXEL_ALPHA`] and
//! scaled by the user's intensity; the contrast test below proves text on the
//! darkest possible textured pixel still meets WCAG AA.

use crate::color::Color;
use crate::kinds::ColorScheme;

/// Peak texel alpha in the generated tiles (keep in sync with the generator).
pub const MAX_TEXEL_ALPHA: f32 = 0.12;

/// Texel colours per scheme (generator `TONES`).
pub const TEXEL_LIGHT: Color = Color::rgb(0x5A, 0x44, 0x2C);
pub const TEXEL_DARK: Color = Color::rgb(0xF3, 0xEC, 0xDD);

/// Shipped sets; `none` draws plain fills.
pub const SETS: &[&str] = &["none", "grain", "fibre", "laid"];

/// File name of a set's tile for a scheme, or `None` for `none`/unknown.
pub fn tile_file(set: &str, scheme: ColorScheme) -> Option<String> {
    (set != "none" && SETS.contains(&set)).then(|| format!("{set}-{}.png", scheme.slug()))
}

/// Cached, intensity-baked file name (the shell writes it under
/// `$XDG_CACHE_HOME/glaze/textures/`).
pub fn baked_file(set: &str, scheme: ColorScheme, intensity: f64) -> Option<String> {
    let pct = (intensity.clamp(0.0, 1.0) * 100.0).round() as u32;
    (pct > 0)
        .then(|| tile_file(set, scheme))
        .flatten()
        .map(|f| f.replace(".png", &format!("-{pct}.png")))
}

/// Scale one alpha byte by intensity (what the shell does per pixel).
pub fn scale_alpha(a: u8, intensity: f64) -> u8 {
    ((a as f64) * intensity.clamp(0.0, 1.0)).round() as u8
}

/// The worst-case (most contrast-reducing) colour of a surface covered by the
/// texture at full intensity.
pub fn worst_case_surface(surface: Color, scheme: ColorScheme) -> Color {
    let texel = match scheme {
        ColorScheme::Light => TEXEL_LIGHT,
        ColorScheme::Dark => TEXEL_DARK,
    };
    texel.over(surface, MAX_TEXEL_ALPHA)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::kinds::ThemeKind;
    use crate::theme::ThemeTokens;

    #[test]
    fn file_names() {
        assert_eq!(
            tile_file("grain", ColorScheme::Dark).as_deref(),
            Some("grain-dark.png")
        );
        assert_eq!(tile_file("none", ColorScheme::Light), None);
        assert_eq!(tile_file("velvet", ColorScheme::Light), None);
        assert_eq!(
            baked_file("fibre", ColorScheme::Light, 0.4).as_deref(),
            Some("fibre-light-40.png")
        );
        assert_eq!(baked_file("fibre", ColorScheme::Light, 0.0), None);
        assert_eq!(scale_alpha(30, 0.5), 15);
    }

    /// Contrast gate: text on a fully textured surface still meets AA.
    #[test]
    fn text_stays_readable_on_textured_surfaces() {
        for kind in ThemeKind::ALL {
            for scheme in ColorScheme::ALL {
                let p = ThemeTokens::for_kind(kind, scheme).palette;
                for (fg, bg, min) in [
                    (p.text_primary, p.panel, 4.5),
                    (p.text_primary, p.surface_raised, 4.5),
                    (p.text_secondary, p.panel, 3.0),
                    (p.ink, p.panel, 3.0),
                ] {
                    let worst = worst_case_surface(bg, scheme);
                    let r = fg.contrast_ratio(worst);
                    assert!(r >= min, "{kind:?}/{scheme:?}: {r:.2} < {min}");
                }
            }
        }
    }

    #[test]
    fn shipped_tiles_exist() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../assets/textures");
        for set in SETS.iter().filter(|s| **s != "none") {
            for scheme in ColorScheme::ALL {
                let f = dir.join(tile_file(set, scheme).unwrap());
                let bytes = std::fs::read(&f).unwrap_or_else(|e| panic!("{}: {e}", f.display()));
                assert_eq!(&bytes[..8], b"\x89PNG\r\n\x1a\n");
            }
        }
    }
}
